#include <bits/stdc++.h>
using namespace std;
#define INF_VAL 1e9+9
#define PII pair<int,int>
#define PPI pair<PII,int>
#define LL long long

struct Edge {
    int u, v, flow, capacity;
    Edge(int u, int v, int flow, int capacity) : u(u), v(v), flow(flow), capacity(capacity) {}
};

int s, t;
vector<vector<int>> adj;
vector<Edge> edges;

void addEdge(int u, int v, int cap) {
    adj[u].push_back(edges.size());
    edges.emplace_back(u, v, 0, cap);
    adj[v].push_back(edges.size());
    edges.emplace_back(v, u, 0, 0);
}

int ptr[1001], dist[1001];

bool bfs() {
    memset(dist, -1, sizeof(dist));
    dist[s] = 0;
    queue<int> q; q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int id : adj[u]) {
            int v = edges[id].v;
            if (dist[v] == -1 && edges[id].flow < edges[id].capacity) {
                dist[v] = dist[u] + 1;
                q.push(v);
                if (v == t) return true;
            }
        }
    }
    return false;
}

long long pushFlow(int u, long long flow) {
    if (flow == 0 || u == t) return flow;
    for (; ptr[u] < adj[u].size(); ++ptr[u]) {
        int id = adj[u][ptr[u]];
        int v = edges[id].v;
        if (dist[v] == dist[u] + 1 && edges[id].flow < edges[id].capacity) {
            long long pushed = pushFlow(v, min(flow, (long long)(edges[id].capacity - edges[id].flow)));
            if (pushed > 0) {
                edges[id].flow += pushed;
                edges[id ^ 1].flow -= pushed;
                return pushed;
            }
        }
    }
    return 0;
}

long long maxFlow() {
    long long total = 0;
    while (bfs()) {
        memset(ptr, 0, sizeof(ptr));
        while (long long pushed = pushFlow(s, LLONG_MAX))
            total += pushed;
    }
    return total;
}

string sci[101], reac[101];
bool reach[10][10][10][10];
int visited[101][101];
int turnsUnusable[10][10];
int n, m;

bool validPos(int r, int c) {
    return r >= 0 && c >= 0 && r < n && c < m;
}

int getID(int x, int y) {
    return 1 + m * x + y;
}

int main() {
    ios::sync_with_stdio(false);
    int T; cin >> T; T++;
    n = m;
    s = 0;
    t = m * m * 2 + 1;
    adj.resize(m * m * 2 + 2);
    for (int i = 0; i < n; ++i) cin >> sci[i];
    for (int i = 0; i < n; ++i) {
        cin >> reac[i];
        for (int j = 0; j < m; ++j) {
            turnsUnusable[i][j] = INF_VAL;
            if (reac[i][j] == 'Z') {
                queue<PII> q; q.push({i, j});
                turnsUnusable[i][j] = 1;
            }
        }
    }
    // BFS for 'Z'
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (reac[i][j] == 'Z') {
                queue<PII> q; q.push({i, j});
                while (!q.empty()) {
                    auto [x, y] = q.front(); q.pop();
                    for (int dx = -1; dx <= 1; ++dx) {
                        for (int dy = -1; dy <= 1; ++dy) {
                            if (abs(dx) + abs(dy) == 1) {
                                int nx = x + dx, ny = y + dy;
                                if (validPos(nx, ny) && turnsUnusable[nx][ny] == INF_VAL && sci[nx][ny] != 'Y') {
                                    turnsUnusable[nx][ny] = turnsUnusable[x][y] + 1;
                                    q.push({nx, ny});
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    // Build graph
    for (int x = 0; x < n; ++x) {
        for (int y = 0; y < m; ++y) {
            if (sci[x][y] >= '1' && sci[x][y] <= '9')
                addEdge(s, getID(x, y), sci[x][y] - '0');
            if (reac[x][y] >= '1' && reac[x][y] <= '9')
                addEdge(n * n + getID(x, y), t, reac[x][y] - '0');
            for (int X = 0; X < n; ++X) {
                for (int Y = 0; Y < m; ++Y) {
                    if (sci[x][y] == 'Y' || sci[x][y] == 'Z' || reac[X][Y] == 'Y' || reac[X][Y] == 'Z') continue;
                    memset(visited, 0, sizeof(visited));
                    std::queue<pairPi> q; q.push({{x, y}, 1});
                    visited[x][y] = 1;
                    while (!q.empty()) {
                        auto [pos, t] = q.front(); q.pop();
                        int xx = pos.first, yy = pos.second;
                        if (xx == X && yy == Y) {
                            visited[xx][yy] = 1; break;
                        }
                        if (t >= turnsUnusable[xx][yy] || t >= T) continue;
                        for (int dx = -1; dx <= 1; ++dx) {
                            for (int dy = -1; dy <= 1; ++dy) {
                                if (abs(dx) + abs(dy) == 1) {
                                    int nx = xx + dx, ny = yy + dy;
                                    if (validPos(nx, ny) && !visited[nx][ny] && sci[nx][ny] != 'Y' && sci[nx][ny] != 'Z' && t + 1 <= turnsUnusable[nx][ny]) {
                                        visited[nx][ny] = 1;
                                        q.push({{nx, ny}, t + 1});
                                    }
                                }
                            }
                        }
                    }
                    if (visited[X][Y]) {
                        addEdge(getID(x, y), n * n + getID(X, Y), INF);
                    }
                }
            }
        }
    }
    long long maxFlowVal = maxFlow();
    std::cout << maxFlowVal << "\n";
    return 0;
}
